package app.noir.mobile;

import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;

/** Device policy and profile state; no UI, Android services or network access. */
public final class PhoneReady {
 public static final int PICKUP_LIMIT=3;
 public static final long GB=1024L*1024*1024,DEFAULT_BUDGET=5*GB,FREE_FLOOR=2*GB,SEVEN_DAYS=7*86400000L,DAY=86400000L,HOUR=3600000L;
 private static final Map<File,PhoneReady> OPEN=new HashMap<>();
 public static synchronized PhoneReady at(File directory){File key=directory.getAbsoluteFile();return OPEN.computeIfAbsent(key,PhoneReady::new);}
 private final File file;private JSONObject state;
 PhoneReady(File directory){file=new File(directory,"phone-ready.json");try{state=new JSONObject(new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));}catch(NoSuchFileException e){state=new JSONObject();}catch(Exception e){throw new IllegalStateException("Couldn't read Keep ready settings",e);}}
 static void put(JSONObject o,String key,Object value){try{o.put(key,value);}catch(JSONException e){throw new IllegalArgumentException(e);}}
 static JSONObject copy(JSONObject o){try{return o==null?new JSONObject():new JSONObject(o.toString());}catch(JSONException e){throw new IllegalArgumentException(e);}}
 static List<JSONObject> objects(JSONArray a){List<JSONObject> r=new ArrayList<>();if(a!=null)for(int n=0;n<a.length();n++){JSONObject o=a.optJSONObject(n);if(o!=null)r.add(o);}return r;}
 public synchronized JSONObject snapshot(){return copy(state);}
 public synchronized JSONObject keepReadyJson(){return copy(state.optJSONObject("shows"));}
 public synchronized boolean enabled(){return state.optBoolean("enabled");}
 public synchronized boolean pickupEnabled(){return state.optBoolean("pickup");}
 public synchronized String pickupReason(){return state.optString("pickupReason");}
 public synchronized void pickupBlocked(String reason){if(!state.optString("pickupReason").equals(reason)){put(state,"pickupReason",reason);save();}if(!reason.isEmpty())log("",reason);}
 public synchronized boolean paused(){return state.optBoolean("paused");}
 public synchronized boolean cleanup(){return !removeCode().equals("never");}
 /* Removal rule codes: never, right, d1, d7, d30. A phone-ready.json from before the rules existed has only the cleanup flag: on reads as d7, off as never. */
 public synchronized String removeCode(){String w=state.optString("removeWhen");if(w.isEmpty())return state.optBoolean("cleanup")?"d7":"never";if(w.equals("right"))return "right";if(w.equals("days")){int d=state.optInt("removeDays",7);return d==1||d==30?"d"+d:"d7";}return "never";}
 public static long delayOf(String code){switch(code==null?"":code){case "right":return HOUR;case "d1":return DAY;case "d7":return SEVEN_DAYS;case "d30":return 30*DAY;default:return -1;}}
 public static String codeOf(String when,int days){return when.equals("right")?"right":when.equals("days")?"d"+(days==1||days==30?days:7):"never";}
 /* The rule that applies to one show: its own choice, else the default. */
 public synchronized String ruleFor(String group){JSONObject m=state.optJSONObject("showRemoval");String own=m==null?"":m.optString(group);return own.isEmpty()?removeCode():own;}
 public synchronized String showRemoval(String group){JSONObject m=state.optJSONObject("showRemoval");return m==null?"":m.optString(group);}
 public synchronized void showRemoval(String group,String code){JSONObject m=copy(state.optJSONObject("showRemoval"));if(code==null||code.isEmpty())m.remove(group);else put(m,group,code);put(state,"showRemoval",m);save();}
 public synchronized String removeScope(){return state.optString("removeScope").equals("all")?"all":"ready";}
 public synchronized boolean removeMovies(){return state.optBoolean("removeMovies");}
 public synchronized int keepWatched(){return Math.max(0,Math.min(3,state.optInt("keepWatched")));}
 public synchronized int ahead(){return validAhead(state.optInt("ahead",2))?state.optInt("ahead",2):2;}
 public static boolean validAhead(int n){return n==-1||n==1||n==2||n==3||n==5;}
 public synchronized String showsMode(){String m=state.optString("showsMode");return m.equals("watching")||m.equals("watchlist")?m:"mine";}
 public synchronized int winStart(){return Math.max(0,Math.min(23,state.optInt("winStart",0)));}
 public synchronized int winEnd(){return Math.max(0,Math.min(23,state.optInt("winEnd",6)));}
 public synchronized boolean needCharging(){return state.optBoolean("needCharging",true);}
 public synchronized boolean wifiOnly(){return state.optBoolean("wifiOnly",true);}
 public synchronized boolean showOff(String group){JSONObject m=state.optJSONObject("showsOff");return m!=null&&m.has(group);}
 /* A show Keep ready should still work on: switched on by the user, or picked by the shows choice and not switched off. */
 public synchronized boolean wanted(String group){return keepReadyJson().has(group)||!showsMode().equals("mine")&&!showOff(group);}
 public synchronized long budget(){return Math.max(GB,state.optLong("budget",DEFAULT_BUDGET));}
 public synchronized void setting(String key,Object value){if(!Arrays.asList("enabled","pickup","paused","cleanup","budget","removeWhen","removeDays","removeScope","removeMovies","keepWatched","ahead","showsMode","winStart","winEnd","needCharging","wifiOnly").contains(key))throw new IllegalArgumentException(key);put(state,key,value);put(state,"reason","");put(state,"pickupReason","");if(key.equals("pickup")&&Boolean.FALSE.equals(value))put(state,"pickupQueue",new JSONArray());if(key.equals("cleanup")){put(state,"removeWhen",Boolean.TRUE.equals(value)?"days":"never");if(Boolean.TRUE.equals(value)&&state.optInt("removeDays",7)!=1&&state.optInt("removeDays",7)!=30)put(state,"removeDays",7);}if(key.equals("cleanup")&&Boolean.FALSE.equals(value))put(state,"removals",new JSONArray());save();}
 public synchronized void keep(String group,boolean enabled){keep(group,enabled?2:0);}
 public synchronized void keep(String group,int count){JSONObject shows=keepReadyJson(),off=copy(state.optJSONObject("showsOff"));if(count==0){shows.remove(group);if(!showsMode().equals("mine"))put(off,group,true);}else{put(shows,group,count==-1||count==-2||count==5?count:Math.max(1,Math.min(3,count)));off.remove(group);}put(state,"shows",shows);put(state,"showsOff",off);save();}
 public synchronized void log(String id,String reason){JSONArray old=state.optJSONArray("why"),next=new JSONArray();List<JSONObject> rows=objects(old);if(!rows.isEmpty()){JSONObject last=rows.get(rows.size()-1);if(last.optString("id").equals(id)&&last.optString("reason").equals(reason))return;}for(int n=Math.max(0,rows.size()-199);n<rows.size();n++)next.put(rows.get(n));JSONObject row=new JSONObject();put(row,"id",id);put(row,"reason",reason);put(row,"at",System.currentTimeMillis());next.put(row);put(state,"why",next);save();}
 public synchronized void blocked(String reason){if(!state.optString("reason").equals(reason)){put(state,"reason",reason);save();}if(!reason.isEmpty())log("",reason);}
 public synchronized String reason(){return state.optString("reason");}
 public synchronized String lastReason(String id){List<JSONObject> rows=objects(state.optJSONArray("why"));for(int n=rows.size()-1;n>=0;n--)if(rows.get(n).optString("id").equals(id))return rows.get(n).optString("reason");return "";}
 public synchronized void retry(String id,long now){JSONObject retries=copy(state.optJSONObject("retries")),r=copy(retries.optJSONObject(id));int tries=Math.min(6,r.optInt("tries")+1);put(r,"tries",tries);put(r,"at",now+Math.min(6*3600000L,15*60000L*(1L<<(tries-1))));put(retries,id,r);put(state,"retries",retries);save();}
 public synchronized boolean canRetry(String id,long now){JSONObject r=state.optJSONObject("retries");return r==null||r.optJSONObject(id)==null||r.optJSONObject(id).optLong("at")<=now;}
 public synchronized void planned(List<JSONObject> items){JSONArray rows=new JSONArray();for(JSONObject i:items){JSONObject r=new JSONObject();for(String key:new String[]{"id","group","title","season","episode"})put(r,key,i.opt(key));rows.put(r);}put(state,"queue",rows);save();}
 public synchronized JSONArray removals(){try{JSONArray rows=state.optJSONArray("removals");return rows==null?new JSONArray():new JSONArray(rows.toString());}catch(JSONException e){throw new IllegalStateException(e);}}
 public synchronized void protect(String id,boolean pin){JSONObject exclusions=copy(state.optJSONObject("exclusions"));put(exclusions,id,pin?"keep":"cancel");put(state,"exclusions",exclusions);JSONArray rows=new JSONArray();for(JSONObject r:objects(state.optJSONArray("removals")))if(!r.optString("id").equals(id))rows.put(r);put(state,"removals",rows);save();log(id,pin?"Kept on this phone":"Removal cancelled");}
 public synchronized boolean protectedFile(String id){JSONObject e=state.optJSONObject("exclusions");return e!=null&&e.has(id);}
 public synchronized void scheduleRemoval(String id,long watchedAt,long now){scheduleRemoval(id,"",watchedAt,now);}
 /* First schedule: watched time plus the rule's wait, never sooner than a day (an hour for "right after") from now. A rule change later: a later date applies at once, an earlier one never lands sooner than now + 1 day. Rows from before the rules existed have no marker and read as 7 days, so they stay as they were. */
 public synchronized void scheduleRemoval(String id,String group,long watchedAt,long now){if(protectedFile(id))return;String rule=ruleFor(group);long delay=delayOf(rule);if(delay<0){forgetRemoval(id);return;}JSONArray rows=removals();for(JSONObject r:objects(rows))if(r.optString("id").equals(id)){if(r.optString("rule","d7").equals(rule))return;long was=r.optLong("at"),fresh=watchedAt+delay;put(r,"at",fresh>=was?fresh:Math.min(was,Math.max(fresh,now+DAY)));put(r,"rule",rule);put(r,"group",group);put(state,"removals",rows);save();log(id,removalText(rule));return;}JSONObject r=new JSONObject();put(r,"id",id);put(r,"at",Math.max(watchedAt+delay,now+(rule.equals("right")?HOUR:DAY)));put(r,"rule",rule);put(r,"group",group);rows.put(r);put(state,"removals",rows);save();log(id,removalText(rule));}
 public static String removalText(String rule){switch(rule){case "right":return "Watched copy scheduled for removal (right after watching)";case "d1":return "Watched copy scheduled for removal (after 1 day)";case "d30":return "Watched copy scheduled for removal (after 30 days)";default:return "Watched copy scheduled for removal";}}
 public static String ruleName(String code){switch(code==null?"":code){case "right":return "Right after watching";case "d1":return "After 1 day";case "d7":return "After 7 days";case "d30":return "After 30 days";default:return "Never";}}
 public synchronized void forgetRemoval(String id){JSONArray rows=new JSONArray();for(JSONObject r:objects(state.optJSONArray("removals")))if(!r.optString("id").equals(id))rows.put(r);put(state,"removals",rows);save();}
 private void save(){try{file.getParentFile().mkdirs();Path temporary=new File(file+".tmp").toPath();Files.write(temporary,state.toString().getBytes(StandardCharsets.UTF_8));try{Files.move(temporary,file.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(temporary,file.toPath(),StandardCopyOption.REPLACE_EXISTING);}}catch(IOException e){throw new IllegalStateException("Couldn't save Keep ready settings",e);}}
 static boolean watched(JSONObject i){JSONObject p=i.optJSONObject("progress");JSONArray v=i.optJSONArray("viewings");return p!=null&&p.optBoolean("completed")||v!=null&&v.length()>0;}
 static long date(String at){try{return Instant.parse(at).toEpochMilli();}catch(Exception e){try{return LocalDate.parse(at.substring(0,10)).atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli();}catch(Exception ignored){return 0;}}}
 static boolean aired(JSONObject i,long now){String at=i.optString("airsAt",i.optString("released"));long when=date(at);return when>0&&when<=now;}
 public static boolean unfinished(JSONObject i){JSONObject p=i==null?null:i.optJSONObject("progress");return p!=null&&p.optDouble("position")>0&&!p.optBoolean("completed");}
 public static List<JSONObject> pickupCandidates(List<JSONObject> items,java.util.function.Predicate<String> local,java.util.function.ToLongFunction<JSONObject> recent){List<JSONObject> rows=new ArrayList<>();Set<String> seen=new HashSet<>();for(JSONObject i:items){String id=i.optString("id");if(!id.isEmpty()&&unfinished(i)&&seen.add(id))rows.add(i);}rows.sort(Comparator.comparingLong(recent).reversed().thenComparing(i->i.optString("id")));return rows;}
 public static List<JSONObject> selectPickup(List<JSONObject> items,java.util.function.Predicate<String> local,java.util.function.Predicate<JSONObject> pcAvailable,java.util.function.ToLongFunction<JSONObject> recent){List<JSONObject> result=new ArrayList<>();int kept=0;for(JSONObject i:pickupCandidates(items,local,recent)){if(local.test(i.optString("id")))kept++;else if(pcAvailable.test(i))result.add(copy(i));if(result.size()+kept>=PICKUP_LIMIT)break;}return result;}
 public synchronized void pickupPlanned(List<JSONObject> items){if(!pickupEnabled())items=Collections.emptyList();JSONArray rows=new JSONArray();for(JSONObject i:items){JSONObject r=new JSONObject();for(String key:new String[]{"id","group","title","season","episode","movie"})put(r,key,i.opt(key));rows.put(r);}if(!rows.toString().equals(String.valueOf(state.optJSONArray("pickupQueue")))){put(state,"pickupQueue",rows);save();}}
 public synchronized String pickupPolicy(boolean paired){return !pickupEnabled()?"Unfinished PC pickup is off":!paired?"Pair with your PC to bring unfinished episodes":paused()?"Keep ready paused":"";}
 public static List<JSONObject> mergeSchedules(List<JSONObject> items,JSONObject shows,JSONObject schedules){Map<String,JSONObject> templates=new HashMap<>(),index=new LinkedHashMap<>();for(JSONObject i:items){String g=i.optString("group");if(!shows.has(g)||i.optBoolean("movie"))continue;templates.putIfAbsent(g,i);index.put(g+":"+i.optInt("season")+":"+i.optInt("episode"),copy(i));}if(schedules!=null)for(String g:templates.keySet())for(JSONObject e:objects(schedules.optJSONArray(g))){int season=e.optInt("season"),episode=e.optInt("episode");if(season<=0||episode<=0)continue;String key=g+":"+season+":"+episode;JSONObject i=index.get(key);if(i==null){i=copy(templates.get(g));i.remove("pcItemId");try{byte[] hash=java.security.MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));StringBuilder hex=new StringBuilder();for(byte b:hash)hex.append(String.format(Locale.ROOT,"%02X",b&255));put(i,"id","episode-"+hex);}catch(java.security.NoSuchAlgorithmException ex){throw new IllegalStateException(ex);}put(i,"season",season);put(i,"episode",episode);put(i,"progress",new JSONObject());put(i,"viewings",new JSONArray());put(i,"available",false);index.put(key,i);}put(i,"airsAt",e.optString("airsAt"));put(i,"episodeTitle",e.optString("title"));}return new ArrayList<>(index.values());}
 public static List<JSONObject> select(List<JSONObject> items,JSONObject shows,long now,int defaultAhead){Map<String,List<JSONObject>> groups=new LinkedHashMap<>();Set<String> started=new HashSet<>();for(JSONObject i:items){String g=i.optString("group");if(!shows.has(g)||i.optBoolean("movie")||i.optInt("season")<=0||i.optInt("episode")<=0)continue;JSONObject p=i.optJSONObject("progress");if(p!=null&&!p.optBoolean("completed")&&p.optDouble("position")>0)started.add(g);if(!watched(i)&&aired(i,now))groups.computeIfAbsent(g,k->new ArrayList<>()).add(i);}List<String> order=new ArrayList<>(groups.keySet());order.sort(Comparator.comparingInt((String g)->started.contains(g)?0:1).thenComparing(g->g));List<JSONObject> result=new ArrayList<>();for(String g:order){List<JSONObject> episodes=groups.get(g);episodes.sort(Comparator.comparingInt((JSONObject e)->e.optInt("season")).thenComparingInt(e->e.optInt("episode")));int requested=shows.optInt(g,-2),count=validAhead(requested)?requested:defaultAhead,season=episodes.get(0).optInt("season"),taken=0;Set<String> seen=new HashSet<>();for(JSONObject e:episodes){if(count==-1&&e.optInt("season")!=season)break;if(count!=-1&&taken>=count)break;if(seen.add(e.optInt("season")+":"+e.optInt("episode"))){result.add(copy(e));taken++;}}}return result;}
 public static List<JSONObject> select(List<JSONObject> items,JSONObject shows,long now){return select(items,shows,now,2);}
 public static long occupied(JSONArray jobs){long n=0;for(JSONObject j:objects(jobs))n=add(n,Math.max(0,j.optLong("diskBytes",j.optLong("bytes"))));return n;}
 public static long reserved(JSONArray jobs,String except){long n=0;for(JSONObject j:objects(jobs))if(!j.optString("id").equals(except)&&!j.optString("status").equals("complete")&&!j.optBoolean("pickupCancelled"))n=add(n,Math.max(0,j.optLong("total")-j.optLong("diskBytes",j.optLong("bytes"))));return n;}
 static long add(long a,long b){return Long.MAX_VALUE-a<b?Long.MAX_VALUE:a+b;}
 public static String storageReason(long used,long reserved,long remaining,long budget,long free){if(remaining<0)return "Waiting for a confirmed file size";long extra=add(Math.max(0,reserved),remaining);if(used>budget||extra>Math.max(0,budget-used))return "Keep ready paused: phone budget reached";if(free<FREE_FLOOR||extra>free-FREE_FLOOR)return "Keep ready paused: keeping 2 GB free";return "";}
 public static boolean cleanupEligible(JSONObject job,JSONObject item,boolean consent,boolean anotherUnfinished,boolean protectedFile){return cleanupEligible(job,item,consent,anotherUnfinished,protectedFile,false,false);}
 /* Keep ready copies (including PC pickup movies) are always in scope. With scope "all", completed manual downloads Noir recorded (noirManual) join; their movies only when asked. Pinned and protected files never. */
 public static boolean cleanupEligible(JSONObject job,JSONObject item,boolean consent,boolean anotherUnfinished,boolean protectedFile,boolean scopeAll,boolean movies){boolean managed=job.optBoolean("readyManaged"),manual=scopeAll&&!managed&&job.optBoolean("noirManual")&&(movies||item==null||!item.optBoolean("movie"));return consent&&(managed||manual)&&!job.optBoolean("pinned")&&!protectedFile&&job.optString("status").equals("complete")&&item!=null&&watched(item)&&!unfinished(item)&&!anotherUnfinished;}
 /* The N most recently watched episodes of every show stay (A3). */
 public static Set<String> shielded(List<JSONObject> items,int n){Set<String> ids=new HashSet<>();if(n<=0)return ids;Map<String,List<JSONObject>> byGroup=new HashMap<>();for(JSONObject i:items)if(!i.optBoolean("movie")&&i.optInt("season")>0&&!i.optString("group").isEmpty()&&watched(i))byGroup.computeIfAbsent(i.optString("group"),k->new ArrayList<>()).add(i);for(List<JSONObject> g:byGroup.values()){g.sort(Comparator.comparingLong((JSONObject i)->watchedAt(i)).thenComparingInt((JSONObject i)->i.optInt("season")).thenComparingInt((JSONObject i)->i.optInt("episode")).reversed());for(int k=0;k<Math.min(n,g.size());k++)ids.add(g.get(k).optString("id"));}return ids;}
 /* Shows Keep ready works on: the ones switched on, plus (by choice) shows being watched and the watchlist, minus shows switched off. Value -2 means "same as the default". */
 public synchronized JSONObject effectiveShows(List<JSONObject> items){JSONObject result=keepReadyJson();String mode=showsMode();if(mode.equals("mine"))return result;Set<String> started=new HashSet<>(),blocked=new HashSet<>(),listed=new HashSet<>(),all=new LinkedHashSet<>();for(JSONObject i:items){String g=i.optString("group");if(g.isEmpty()||i.optBoolean("movie"))continue;all.add(g);JSONObject pr=i.optJSONObject("progress");if(watched(i)||pr!=null&&pr.optDouble("position")>0)started.add(g);if(i.optBoolean("hidden")||i.optString("status").equals("Dropped"))blocked.add(g);if(i.optBoolean("listed"))listed.add(g);}for(String g:all)if(!blocked.contains(g)&&!showOff(g)&&!result.has(g)&&(started.contains(g)||mode.equals("watchlist")&&listed.contains(g)))put(result,g,-2);return result;}
 public static long watchedAt(JSONObject item){long at=0;JSONObject p=item.optJSONObject("progress");if(p!=null&&p.optBoolean("completed"))at=date(p.optString("updatedAt"));for(JSONObject v:objects(item.optJSONArray("viewings")))if(!v.optBoolean("dateUnknown"))at=Math.max(at,date(v.optString("watchedAt")));return at;}
 /* The window may cross midnight; start equal to end means any time. */
 public static boolean inWindow(int hour,int start,int end){return start==end||(start<end?hour>=start&&hour<end:hour>=start||hour<end);}
 public static boolean overnight(int hour){return inWindow(hour,0,6);}
}
